    // csv
    function parseCSV(text) {
      var rows = [],
        row = [],
        cur = "",
        q = false;
      for (var i = 0; i < text.length; i++) {
        var c = text[i];
        if (q) {
          if (c === '"') {
            if (text[i + 1] === '"') {
              cur += '"';
              i++;
            } else q = false;
          } else cur += c;
        } else if (c === '"') q = true;
        else if (c === ",") {
          row.push(cur);
          cur = "";
        } else if (c === "\n" || c === "\r") {
          if (c === "\r" && text[i + 1] === "\n") i++;
          row.push(cur);
          rows.push(row);
          row = [];
          cur = "";
        } else cur += c;
      }
      if (cur || row.length) {
        row.push(cur);
        rows.push(row);
      }
      return rows
        .map(function (r) {
          return r.map(function (x) {
            return x.trim();
          });
        })
        .filter(function (r) {
          return r.some(Boolean);
        });
    }
    function readFile(input, cb, msg) {
      var f = input.files[0];
      if (!f) return;
      if (f.size > 1024 * 1024) {
        msg("That file is too large. Keep it under 1 MB.");
        return;
      }
      var r = new FileReader();
      r.onload = function () {
        cb(String(r.result));
      };
      r.readAsText(f);
    }
    function note(id) {
      return function (m) {
        var e = $(id);
        e.textContent = m;
      };
    }

